import{_ as o,a0 as l,w as a,s as p,ao as s,I as r,x as e,a1 as u,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"‘Unity Greeter Badges’：將丟失的會話圖標帶回Ubuntu登錄屏幕 | LCTT x X-CMD","titleTemplate":false,"description":"‘Unity Greeter Badges’：將丟失的會話圖標帶回Ubuntu登錄屏幕 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"‘Unity Greeter Badges’：將丟失的會話圖標帶回Ubuntu登錄屏幕 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"‘Unity Greeter Badges’：將丟失的會話圖標帶回Ubuntu登錄屏幕 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150119 Unity Greeter Badges Brings Missing Session Icons to Ubuntu Login Screen","title":"‘Unity Greeter Badges’：將丟失的會話圖標帶回Ubuntu登錄屏幕","tag":"201505","desc":""},"relativePath":"201505/20150119 Unity Greeter Badges Brings Missing Session Icons to Ubuntu Login Screen.md","filePath":"[post].md"}'),g={name:"201505/20150119 Unity Greeter Badges Brings Missing Session Icons to Ubuntu Login Screen.md"};function d(b,t,m,U,T,f){const n=l("Link");return a(),p("div",null,[t[18]||(t[18]=s('<h1 id="unity-greeter-badges-將丟失的會話圖標帶回ubuntu登錄屏幕" tabindex="-1">‘Unity Greeter Badges’：將丟失的會話圖標帶回Ubuntu登錄屏幕 <a class="header-anchor" href="#unity-greeter-badges-將丟失的會話圖標帶回ubuntu登錄屏幕" aria-label="Permalink to “‘Unity Greeter Badges’：將丟失的會話圖標帶回Ubuntu登錄屏幕”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/01/unity-greeter-badges-750x321.jpg" alt=""></p><p>新出現在<strong>Ubuntu 15.04中的一個軟件包解決了我對Unity 歡迎屏的微詞：像Cinnamon這樣的其它Linux桌面會話沒有徽章圖標。</strong></p><p>我知道這有點吹毛求疵了；這只是對大多數人而言幾乎毫無影響的視覺瑕疵罷了。但是這種不一致性時時刻刻纏繞着我，讓我不勝其煩，因為Ubuntu的一些會話帶有徽章圖標，包括Unity、GNOME和KDE。而剩下的其它桌面環境，包括它自己的一些旁系產品，像Xubuntu，只會在會話切換列表和主用户界面顯示了一個不能再簡單的白點。</p><p>這些點點們造成的這種不一致性刺激着我的神經，即使它只是稍縱即逝，但這種刺激不僅僅來自設計，也來自可用性方面。標牌式的標誌符號對於讓我們知道我們即將登陸到哪個會話很有幫助。</p><p>例如，你能告訴我們這個是個什麼會話呢？</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2015/01/what-session-is-this-750x247.jpg" alt=""></p><p>Budgie? 也許是 MATE? 也能是 Cinnamon……我必須點開它才能知道。</p><p>沒有必要這樣做啊。構建Unity Greeter，就是為了讓桌面環境開發者能夠部署徽章到歡迎屏幕中（有些確實這樣做了）。但在許多情況下，像MATE，它的包來自上游的Debian，想要移植一個“Ubuntu專用的補丁包”不太可取，也不太可能。</p><h3 id="一個解決方案出爐了" tabindex="-1">一個解決方案出爐了 <a class="header-anchor" href="#一個解決方案出爐了" aria-label="Permalink to “一個解決方案出爐了”">​</a></h3>',10)),r("p",null,[t[1]||(t[1]=e("一位有經驗的Debian維護者",-1)),u(n,{href:"https://launchpad.net/~profzoom"},{default:i(()=>[...t[0]||(t[0]=[e("Doug Torrance",-1)])]),_:1}),t[2]||(t[2]=e("有了修復該可用性瑕疵的解決方案。與其依賴桌面製造者自己來添加品牌式徽章到他們的包中，與其給Ubuntu增加維護它的責任重擔，Torrance還不如自己創建了一個獨立的‘unity-greeter-badges’包來收容它們。",-1))]),t[19]||(t[19]=s("<p>承擔起了直接提供會話標誌的假定責任後，該包確保能同時迎合新舊窗口管理器、會話和桌面。</p><p>在30個左右的桌面環境列表中，它為以下桌面捆綁了新的會話徽章：</p><ul><li>Xubuntu</li><li>Cinnamon</li><li>MATE</li><li>Cairo-Dock</li><li>Xmonad</li><li>Awesome</li><li>OpenBox</li><li>Pantheon</li></ul><p>最重要的是，‘<strong>Unity-Greeter-Badges</strong>’已經被Ubuntu 15.04收錄進去。這就意味着Torrance的包將可以直接安裝，不需要PPA，也不需要下載。沒有像Unity Greeter一樣成為核心包的一部分，它可以以更高效和更及時的方式更新新的圖標。</p><p>如果你真運行着Ubuntu 15.04，在不久的將來，你就可以從軟件中心獲取並安裝該包了。</p><p>不想等到15.04？Torrance已經為Ubuntu 14.04和Ubuntu 14.10用户做了個.deb安裝器。</p>",6)),r("ul",null,[r("li",null,[u(n,{href:"https://launchpad.net/~profzoom/+archive/ubuntu/misc/+files/unity-greeter-badges_0.1-0ubuntu1%7E201412111501%7Eubuntu14.04.1_all.deb"},{default:i(()=>[...t[3]||(t[3]=[e("下載用於Ubuntu 14.04的unity-greeter-badges",-1)])]),_:1})]),r("li",null,[u(n,{href:"https://launchpad.net/~profzoom/+archive/ubuntu/misc/+files/unity-greeter-badges_0.1-0ubuntu1%7E201412111501%7Eubuntu14.10.1_all.deb"},{default:i(()=>[...t[4]||(t[4]=[e("下載用於Ubuntu 14.10的unity-greeter-badges",-1)])]),_:1})])]),t[20]||(t[20]=r("hr",null,null,-1)),r("p",null,[t[6]||(t[6]=e("via: ",-1)),u(n,{href:"http://www.omgubuntu.co.uk/2015/01/unity-greeter-badges-brings-missing-session-icons-ubuntu-login-screen"},{default:i(()=>[...t[5]||(t[5]=[e("http://www.omgubuntu.co.uk/2015/01/unity-greeter-badges-brings-missing-session-icons-ubuntu-login-screen",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("作者：",-1)),u(n,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:i(()=>[...t[7]||(t[7]=[e("Joey-Elijah Sneddon",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),u(n,{href:"https://github.com/GOLinux"},{default:i(()=>[...t[8]||(t[8]=[e("GOLinux",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),u(n,{href:"https://github.com/wxy"},{default:i(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[15]||(t[15]=e("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創翻譯，",-1)),u(n,{href:"http://linux.cn/"},{default:i(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const B=o(g,[["render",d]]);export{x as __pageData,B as default};
